// 🏫 St. Eugene 7 (§24) — what a lesson is made of.
//
// A lesson is a QUEUE OF BLOCKS. Five kinds, and nothing else: something to
// read, something to pick, something to build, something to watch, something
// to play. The lesson engine (`src/logic/steugeneLesson.ts`) shuffles them into
// a run long enough to fill the clock; the player (`src/components/steugene/`)
// draws them.
//
// Every block is DATA. That is the whole reason this file exists: a block
// written by hand in a pack and a block generated by the AI on Dad's say-so
// (§24h) are the same shape, so the player cannot tell them apart and nothing
// downstream has to care.

/** How a mark on a drawing is coloured. */
export type SeTone = 'good' | 'bad' | 'focus' | 'calm'

/**
 * The little pixel sprites (`src/components/steugene/art/sprites.tsx`). Drawn
 * in code, so they cost no storage and stay sharp at any size.
 */
export type SeIcon =
  | 'diamond'
  | 'emerald'
  | 'gold'
  | 'iron'
  | 'coal'
  | 'redstone'
  | 'heart'
  | 'drumstick'
  | 'pickaxe'
  | 'sword'
  | 'grass'
  | 'stone'
  | 'plank'
  | 'tnt'
  | 'chest'
  | 'xp'
  | 'apple'
  | 'cookie'
  | 'egg'
  | 'pizza'
  | 'ball'
  | 'trophy'
  | 'vbuck'
  | 'robux'
  | 'pokeball'
  | 'potion'
  | 'star'
  | 'skull'
  | 'player'
  | 'torch'

/** A Minecraft block face, for the grids and boxes. */
export type SeTile = 'grass' | 'dirt' | 'stone' | 'plank' | 'glass' | 'water' | 'sand' | 'wool' | 'brick' | 'gold' | 'diamond' | 'obsidian'

/** A point on the Cartesian plane, optionally named and drawn as a sprite. */
export interface SePlanePoint {
  x: number
  y: number
  label?: string
  tone?: SeTone
  icon?: SeIcon
}

/**
 * The drawings. Deliberately a closed set rather than free SVG: he has trouble
 * reading, so almost every block wants a picture, and a picture that takes ten
 * minutes to author never gets authored. Every one of these is one line.
 *
 * Every drawing animates in when its card appears — slices slide out, blocks
 * drop in, the storm pulses, the hops arc along the line — because a moving
 * picture is the one he actually looks at. None of it ever gives the answer
 * away: a drawing on a question shows the situation, never the result.
 */
export type SeArt =
  /** A number line. The workhorse — integers, fractions, negatives, distance. */
  | {
      art: 'numberline'
      from: number
      to: number
      /** Gap between labelled ticks. Defaults to 1. */
      step?: number
      points?: { at: number; label?: string; tone?: SeTone }[]
      /** Shade the span between two values — "how far apart", visually. */
      span?: [number, number]
      /** Jumps drawn as arcs, one after another — "start at −3, go up 7". */
      hops?: { from: number; to: number; label?: string; tone?: SeTone }[]
    }
  /**
   * A Minecraft world, cut open: sky, grass, stone, deepslate, bedrock, with
   * the Y numbers up the side exactly as F3 shows them. Negative numbers are
   * literally underground here.
   */
  | {
      art: 'ylevel'
      from: number
      to: number
      step?: number
      marks?: { at: number; label?: string; icon?: SeIcon; tone?: SeTone }[]
      /** A mine shaft between two levels — the distance, made visible. */
      dig?: [number, number]
    }
  /** A thermometer — Toronto in January is a negative number nobody argues with. */
  | { art: 'thermo'; from: number; to: number; step?: number; at: number; label?: string; marks?: { at: number; label?: string }[] }
  /** A Minecraft health (or hunger) bar: 10 icons, halves allowed. `lost` ones flash and break. */
  | { art: 'hearts'; full: number; max?: number; lost?: number; kind?: 'heart' | 'drumstick'; label?: string }
  /** Fortnite's shield-over-health bars. Starting values only; the answer is never drawn. */
  | { art: 'hp'; health: number; shield?: number; max?: number; label?: string }
  /**
   * The Fortnite storm: a safe circle with the storm wall pulsing outside it.
   * Radius and diameter are drawn as lines with whatever label you give them
   * ("120 m", "?"); `ring` sends a runner round the edge for circumference;
   * `next` draws the next, smaller circle at that fraction of this one.
   */
  | { art: 'storm'; r?: string; d?: string; ring?: string; next?: number; label?: string }
  /**
   * Real pizzas. `take` slices slide out (the fraction you are pointing at),
   * `gone` slices have been eaten. Several pizzas side by side for anything
   * bigger than one, and `size` (0.4–1) to put a small one next to a large.
   */
  | { art: 'pizza'; pies: { slices: number; take?: number; gone?: number; size?: number; label?: string }[]; label?: string }
  /**
   * A top-down Minecraft floor, w × h blocks. `holes` cut pieces out (an L-shaped
   * base), `paint` lays a different block over a region, `edge` marches round
   * the outside for perimeter. `wLabel` / `hLabel` name the sides.
   */
  | {
      art: 'blocks'
      w: number
      h: number
      tile?: SeTile
      holes?: [number, number, number, number][]
      paint?: { x: number; y: number; w: number; h: number; tile: SeTile }[]
      wLabel?: string
      hLabel?: string
      edge?: boolean
      label?: string
    }
  /**
   * A 3-D solid. `rect` is a box of blocks you can count (with `water` layers
   * rising inside a glass one), `tri` is a roof-shaped triangular prism,
   * `circle` is a cylinder. The labels name the edges.
   */
  | {
      art: 'prism'
      base: 'rect' | 'tri' | 'circle'
      l: number
      w: number
      h: number
      tile?: SeTile
      water?: number
      labels?: { l?: string; w?: string; h?: string }
      label?: string
    }
  /** The Cartesian plane — or the F3 screen's X and Z. Points, segments, shapes and y = mx + b lines. */
  | {
      art: 'plane'
      x: [number, number]
      y: [number, number]
      step?: number
      xName?: string
      yName?: string
      points?: SePlanePoint[]
      segs?: { from: [number, number]; to: [number, number]; tone?: SeTone; dash?: boolean }[]
      polys?: { pts: [number, number][]; tone?: SeTone; label?: string; dash?: boolean }[]
      lines?: { m: number; b: number; tone?: SeTone; label?: string }[]
    }
  /**
   * An angle, swept open. `split` adds a ray inside it so the two parts can be
   * labelled (complementary, supplementary); `cross` draws two crossing lines
   * with four labelled angles (vertically opposite).
   */
  | { art: 'angle'; deg: number; label?: string; split?: number; labels?: [string, string]; cross?: [string, string, string, string] }
  /**
   * Any polygon, fitted to the frame. Sides and angles can be labelled, equal
   * sides ticked, right angles boxed. `also` draws more shapes beside it, for
   * congruent / similar / before-and-after.
   */
  | {
      art: 'shape'
      pts: [number, number][]
      sides?: (string | null)[]
      angles?: (string | null)[]
      ticks?: number[]
      right?: number[]
      tone?: SeTone
      label?: string
      also?: { pts: [number, number][]; sides?: (string | null)[]; angles?: (string | null)[]; tone?: SeTone; label?: string }[]
    }
  /**
   * Code. `blocks` draws it Scratch-style, coloured by what each line does;
   * `text` is Roblox-Studio-style Lua with the keywords lit. `hl` lines light
   * up one after another, like the program running; `out` is the console.
   */
  | { art: 'code'; lines: string[]; style?: 'blocks' | 'text'; hl?: number[]; out?: string[] }
  /** A small table — pattern rules, data, a scoreboard. */
  | { art: 'table'; head: string[]; rows: (string | number)[][]; hl?: { r?: number; c?: number } }
  /** Countable sprites, in rows. `per` leaves a gap every so many; `dim` greys out the last few. */
  | { art: 'items'; rows: { icon?: SeIcon; emoji?: string; n: number; label?: string; per?: number; dim?: number }[] }
  /** Minecraft inventory slots: an item and a count in the corner. `null` is an empty slot. */
  | { art: 'slots'; slots: ({ icon: SeIcon; n?: number } | null)[]; cols?: number; label?: string }
  /** A spinner, weighted by `n`. It spins when the card opens — probability you can watch. */
  | { art: 'spinner'; parts: { label: string; n?: number; tone?: SeTone }[] }
  /** Dice faces. */
  | { art: 'dice'; faces: number[] }
  /** Shop cards side by side — bundles, sale prices (`was`), a ribbon `tag`. */
  | { art: 'shop'; offers: { icon?: SeIcon; emoji?: string; qty: string; price: string; was?: string; tag?: string }[] }
  /** A till receipt. */
  | { art: 'receipt'; lines: { item: string; price: string }[]; total?: string; note?: string }
  /** A vertical bar chart or a line graph, animating in. */
  | { art: 'chart'; type: 'bar' | 'line'; labels: string[]; values: number[]; unit?: string; max?: number; title?: string }
  /** A circle graph with a legend. */
  | { art: 'circlegraph'; slices: { label: string; value: number }[]; unit?: string }
  /** A fraction bar: `filled` of `parts` shaded. */
  | { art: 'bar'; parts: number; filled: number; label?: string; tone?: SeTone }
  /** The same thing as a circle, for when the question is about pizza. */
  | { art: 'pie'; parts: number; filled: number; label?: string; tone?: SeTone }
  /** Integer counters: red minuses and green pluses, cancelling in pairs. */
  | { art: 'counters'; pos: number; neg: number; cancel?: boolean }
  /** A balance scale — the picture that makes "do it to both sides" obvious. */
  | { art: 'scale'; left: string; right: string; tilt?: -1 | 0 | 1 }
  /** Proportional bars, for comparing quantities without a chart library. */
  | { art: 'bars'; rows: { label: string; value: number; tone?: SeTone }[]; unit?: string }

/** A callout inside an explanation. Four flavours, same as the Academy's. */
export interface SeCallout {
  flavour: 'imagine' | 'gotcha' | 'key' | 'pirate'
  text: string
}

/**
 * One step of a worked solution, shown after a WRONG answer.
 *
 * §24f: the walk-through never uses the numbers he just got wrong. He does not
 * get to fix that question, so showing him its answer teaches him to copy;
 * showing him the same move on a different number teaches him the move.
 */
export interface SeStep {
  text: string
  art?: SeArt
}

interface SeBlockBase {
  id: string
  /** Rough seconds, used only to size the opening queue. Never shown to him. */
  secs?: number
}

/** Something to read. Short lines — never a paragraph. */
export interface SeExplain extends SeBlockBase {
  kind: 'explain'
  title: string
  emoji?: string
  /** One idea per line. The reader reads them one at a time. */
  lines: string[]
  art?: SeArt
  callout?: SeCallout
}

/** Multiple choice. Three options (§24f), one right. */
export interface SeChoice extends SeBlockBase {
  kind: 'choice'
  prompt: string
  art?: SeArt
  options: string[]
  /** Index into `options`. */
  answer: number
  /** Said out loud whichever way it goes — the fact, not the verdict. */
  why: string
  /** The didactic walk-through, on a DIFFERENT number. */
  steps?: SeStep[]
}

/**
 * He types it himself — but out of a hand of tiles that already contains every
 * character of the answer, plus decoys (§24f). Reading is the hard part for
 * him; the maths is not, and a blank keyboard tests the wrong thing.
 */
export interface SeBuild extends SeBlockBase {
  kind: 'build'
  prompt: string
  art?: SeArt
  /** Exactly what the tiles must spell, e.g. "-12" or "3/4" or "1.0". */
  answer: string
  /** Decoy tiles. Authored where a good decoy matters; otherwise generated. */
  decoys?: string[]
  why: string
  steps?: SeStep[]
}

/**
 * A video he cannot escape from (§24g): a no-cookie embed with no related
 * videos, no channel link and a shield over the chrome. `checks` are asked
 * AFTER it finishes, which is the entire reason the video is here.
 */
export interface SeVideo extends SeBlockBase {
  kind: 'video'
  youtube: string
  title: string
  /** Who made it — credited on the card, not linked. */
  by?: string
  /** Runtime, for the queue estimate. */
  seconds: number
  /** Start/stop inside a longer video, so a 20-minute upload can give 3 minutes. */
  start?: number
  end?: number
  checks: Omit<SeChoice, 'kind' | 'id'>[]
}

/** The minigames. Three shapes, every one of them tap-only (no dragging). */
export interface SeGame extends SeBlockBase {
  kind: 'game'
  title: string
  /** Order the values smallest → largest by tapping them in sequence. */
  game:
    | { mode: 'order'; values: { label: string; value: number }[] }
    /** Tap a left card, then its partner on the right. */
    | { mode: 'pair'; pairs: [string, string][] }
    /** Tap the spot on a number line where the value lives. */
    | { mode: 'line'; from: number; to: number; step: number; targets: { label: string; at: number }[] }
  why?: string
}

export type SeBlock = SeExplain | SeChoice | SeBuild | SeVideo | SeGame

/**
 * Everything written for one subtopic.
 *
 * `core` is the spine — what he gets the first time, in this order. `extra` is
 * the deep bench: the engine splices from it whenever he is working faster than
 * the clock (§24d), and draws the whole lesson from it when he repeats a
 * subtopic, so a repeat is never the same lesson twice.
 */
export interface SePack {
  subtopicId: string
  core: SeBlock[]
  extra: SeBlock[]
}

// --- The AI desk (§24h) ------------------------------------------------------
//
// He can ask for more. He cannot help himself to more. Every request is a row
// in `app/steugene` that Dad has to approve, and only then does anything get
// generated — with Dad's key, on Dad's device. That is the whole mechanism,
// and it exists because an "unlimited explanations" button pointed at a paid
// API is a bill waiting to happen.

export interface SeAiRequest {
  id: string
  subtopicId: string
  /** A nicety for the notification — "Rational numbers", not "math-rational". */
  subtopicTitle: string
  want: 'questions' | 'explain'
  at: number
  status: 'pending' | 'approved' | 'denied' | 'failed'
  decidedAt?: number
  /** How many blocks actually landed. */
  made?: number
  /** Verbatim, when it failed. A vague reason is worse than a long one. */
  error?: string
  /** He has seen the verdict. */
  seen?: boolean
}

/** One approved batch, appended to the subtopic's bench. */
export interface SeGenerated {
  id: string
  subtopicId: string
  at: number
  blocks: SeBlock[]
}

export interface SeDesk {
  requests: SeAiRequest[]
  generated: SeGenerated[]
}
